{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C31"],
      "claim": "Verapamil, the closest structural analogue sharing dimethoxyphenyl and basic amine motifs, has an absolute oral bioavailability of 34% in humans, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C71"],
      "claim": "In 20 normal young men, verapamil bioavailability averaged 19.4% after oral doses, slightly below the 20% threshold, indicating borderline first-pass metabolism.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C25"],
      "claim": "Valbenazine, a related dimethoxy-substituted tetrahydroisoquinoline-type drug, has an absolute oral bioavailability of approximately 49% in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Noscapine, a dimethoxy-substituted isoquinoline alkaloid, has an absolute oral bioavailability of 30% in healthy volunteers.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Levosulpiride, a related methoxy-substituted basic drug, has an oral bioavailability of about 30% in healthy volunteers.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Encainide, another dimethoxyphenyl-containing basic drug, has an absolute oral bioavailability of 32 ± 7% in normal subjects.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is most similar to verapamil and other dimethoxy-substituted basic amines whose human oral bioavailability is generally 20–50%; despite borderline verapamil values near 19–20%, the weight of transferable evidence supports F ≥20%.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the query molecule.",
    "The exact pharmacological identity and clinical pharmacokinetic profile of the query are unknown.",
    "Verapamil, the closest analogue, straddles the 20% threshold, adding uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

